20	import type Axis from '../coord/Axis';
21	import type { AxisBaseModel } from '../coord/AxisBaseModel';
22	import Axis2D from '../coord/cartesian/Axis2D';
23	import type SingleAxis from '../coord/single/SingleAxis';
24	import type SeriesModel from '../model/Series';
25	import { makeInner } from './model';
26	
27	export function needFixJitter(seriesModel: SeriesModel, axis: Axis): boolean {
28	    const coordinateSystem = seriesModel.coordinateSystem;
29	    const coordType = coordinateSystem && coordinateSystem.type;
30	    const baseAxis = coordinateSystem && coordinateSystem.getBaseAxis && coordinateSystem.getBaseAxis();
31	    const scaleType = baseAxis && baseAxis.scale && baseAxis.scale.type;
32	    const seriesValid = coordType === 'cartesian2d' && scaleType === 'ordinal'
33	        || coordType === 'single';
34	
35	    const axisValid = (axis.model as AxisBaseModel).get('jitter') > 0;
36	    return seriesValid && axisValid;
37	}
38	
39	export type JitterData = {
40	    fixedCoord: number,
41	    floatCoord: number,
42	    r: number,
43	    next: JitterData | null,
44	    prev: JitterData | null
45	};
46	
47	const inner = makeInner<{ items: JitterData }, Axis2D | SingleAxis>();
48	
49	/**
50	 * Fix jitter for overlapping data points.
51	 *
52	 * @param fixedAxis The axis whose coord doesn't change with jitter.
53	 * @param fixedCoord The coord of fixedAxis.
54	 * @param floatCoord The coord of the other axis, which should be changed with jittering.
55	 * @param radius The radius of the data point, considering the symbol is a circle.
56	 * @returns updated floatCoord.
57	 */
58	export function fixJitter(
59	    fixedAxis: Axis2D | SingleAxis,
60	    fixedCoord: number,
61	    floatCoord: number,
62	    radius: number
63	): number {
64	    if (fixedAxis instanceof Axis2D) {
65	        const scaleType = fixedAxis.scale.type;
66	        if (scaleType !== 'category' && scaleType !== 'ordinal') {
67	            return floatCoord;
68	        }
69	    }
70	    const axisModel = fixedAxis.model as AxisBaseModel;
71	    const jitter = axisModel.get('jitter');
72	    const jitterOverlap = axisModel.get('jitterOverlap');
73	    const jitterMargin = axisModel.get('jitterMargin') || 0;
74	    // Get band width to limit jitter range
75	    const bandWidth = fixedAxis.scale.type === 'ordinal'
76	        ? fixedAxis.getBandWidth()
77	        : null;
78	    if (jitter > 0) {
79	        if (jitterOverlap) {
80	            return fixJitterIgnoreOverlaps(floatCoord, jitter, bandWidth, radius);
81	        }
82	        else {
83	            return fixJitterAvoidOverlaps(fixedAxis, fixedCoord, floatCoord, radius, jitter, jitterMargin);
84	        }
85	    }
86	    return floatCoord;
87	}
88	
89	function fixJitterIgnoreOverlaps(
90	    floatCoord: number,
91	    jitter: number,
92	    bandWidth: number | null,
93	    radius: number
94	): number {
95	    // Don't clamp single axis
96	    if (bandWidth === null) {
97	        return floatCoord + (Math.random() - 0.5) * jitter;
98	    }
99	    const maxJitter = bandWidth - radius * 2;
100	    const actualJitter = Math.min(Math.max(0, jitter), maxJitter);
101	    return floatCoord + (Math.random() - 0.5) * actualJitter;
102	}
103	
104	function fixJitterAvoidOverlaps(
105	    fixedAxis: Axis2D | SingleAxis,
106	    fixedCoord: number,
107	    floatCoord: number,
108	    radius: number,
109	    jitter: number,
110	    margin: number
111	): number {
112	    const store = inner(fixedAxis);
113	    if (!store.items) {
114	        store.items = {
115	            fixedCoord: -1,
116	            floatCoord: -1,
117	            r: -1,
118	            next: null,
119	            prev: null
120	        };
121	        store.items.next = store.items;
122	        store.items.prev = store.items;
123	    }
124	    const items = store.items;
125	
126	    const overlapA = placeJitterOnDirection(items, fixedCoord, floatCoord, radius, jitter, margin, 1);
127	    const overlapB = placeJitterOnDirection(items, fixedCoord, floatCoord, radius, jitter, margin, -1);
128	    const overlapResult = Math.abs(overlapA.resultCoord - floatCoord) < Math.abs(overlapB.resultCoord - floatCoord)
129	        ? overlapA : overlapB;
130	    let minFloat = overlapResult.resultCoord;
131	    // Clamp only category axis
132	    const bandWidth = fixedAxis.scale.type === 'ordinal'
133	        ? fixedAxis.getBandWidth()
134	        : null;
135	    const distance = Math.abs(minFloat - floatCoord);
136	    if (distance > jitter / 2
137	        || (bandWidth && distance > bandWidth / 2 - radius)
138	    ) {
139	        // If the new item is moved too far, then give up.
140	        // Fall back to random jitter.
141	        minFloat = fixJitterIgnoreOverlaps(floatCoord, jitter, bandWidth, radius);
142	    }
143	
144	    // Insert to store
145	    const insertBy = overlapResult.insertBy;
146	    const resultDirection = overlapResult.direction;
147	    const pointer1 = resultDirection > 0 ? 'next' : 'prev';
148	    const pointer2 = resultDirection > 0 ? 'prev' : 'next';
149	    const newItem: JitterData = {
150	        fixedCoord: fixedCoord,
151	        floatCoord: overlapResult.resultCoord,
152	        r: radius,
153	        next: null,
154	        prev: null
155	    };
156	    newItem[pointer1] = insertBy[pointer1];
157	    newItem[pointer2] = insertBy;
158	    insertBy[pointer1][pointer2] = newItem;
159	    insertBy[pointer1] = newItem;
160	
161	    return minFloat;
162	}
163	
164	function placeJitterOnDirection(
165	    items: JitterData,
166	    fixedCoord: number,
167	    floatCoord: number,
168	    radius: number,
169	    jitter: number,
170	    margin: number,
171	    direction: 1 | -1
172	): {
173	    resultCoord: number;
174	    insertBy: JitterData;
175	    direction: 1 | -1;
176	} {
177	    // Check for overlap with previous items.
178	    let y = floatCoord;
179	    const pointer1 = direction > 0 ? 'next' : 'prev';
180	    let insertBy = items;
181	    let item = items[pointer1];
182	
183	    while (item !== items) {
184	        const dx = fixedCoord - item.fixedCoord;
185	        const dy = y - item.floatCoord;
186	        const d2 = dx * dx + dy * dy;
187	        const r = radius + item.r + margin;
188	        if (d2 < r * r) {
189	            // Overlap. Try to move the new item along otherCoord direction.
190	            y = item.floatCoord + Math.sqrt(r * r - dx * dx) * direction;
191	            insertBy = item;
192	
193	            if (Math.abs(y - floatCoord) > jitter / 2) {
194	                // If the new item is moved too far, then give up.
195	                // Fall back to random jitter.
196	                return {resultCoord: Number.MAX_VALUE, insertBy, direction};
197	            }
198	        }
199	
200	        item = item[pointer1];
201	    }
202	
203	    return {resultCoord: y, insertBy, direction};
204	}
