20	import type GlobalModel from '../../model/Global';
21	import type ScatterSeriesModel from './ScatterSeries';
22	import { needFixJitter, fixJitter } from '../../util/jitter';
23	import type SingleAxis from '../../coord/single/SingleAxis';
24	import type Axis2D from '../../coord/cartesian/Axis2D';
